package com.hulk.manualledger

import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import org.junit.After
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith

/** Product contracts using the same persisted tree and export entry point as the UI.
 * Run ONLY in the offline acceptance package generated by prepare.py. No real DB is opened.
 */
@RunWith(AndroidJUnit4::class)
class ProductCategoryAcceptanceTest {
    private lateinit var db: ManualLedgerDatabase
    private lateinit var repo: ManualLedgerRepository

    @Before fun setUp() {
        check(ApplicationProvider.getApplicationContext<android.content.Context>().packageName ==
            "com.hulk.manualledger.acceptance") { "Acceptance package required" }
        db = Room.inMemoryDatabaseBuilder(ApplicationProvider.getApplicationContext(),
            ManualLedgerDatabase::class.java).allowMainThreadQueries().build()
        repo = ManualLedgerRepository(db)
    }
    @After fun close() { if (::db.isInitialized) db.close() }
    private fun input(path: String) = NewManualTransaction(stableId = "acceptance-only",
        type = ManualTransactionType.EXPENSE, amountText = "12.34", category = path,
        account = "验收账户", occurredAtMs = 1700000000000, preserveCategoryPath = true)

    @Test fun editingOnlyNoteMustKeepPromotedCategory() {
        repo.import(listOf(input("饮食 › 早餐")))
        val breakfast = repo.categories().first { it.name == "早餐" }
        repo.moveCategory(breakfast.id, null)
        assertEquals("早餐", repo.list().single().category)
        repo.update("acceptance-only", input("早餐").copy(note = "只改备注"))
        assertEquals("Editing a note must not change category", "早餐", repo.list().single().category)
    }

    @Test fun analysisMustRespectMovedCategoryRoot() {
        repo.import(listOf(input("饮食 › 早餐")))
        val breakfast = repo.categories().first { it.name == "早餐" }
        val shopping = repo.categories().first { it.name == "购物" && it.parentId == null }
        repo.moveCategory(breakfast.id, shopping.id)
        val row = repo.list().single()
        assertEquals("购物 › 早餐", row.category)
        // Same default resolution as MainActivity.resolveCategory.
        assertEquals("Analytics must follow the managed tree", "购物",
            CategoryTree.rootName(row, repo.categories()))
    }

    @Test fun deletedBuiltInMustDisappearFromNewEntryOptions() {
        val breakfast = repo.categories().first { it.name == "早餐" }
        repo.deleteCategory(breakfast.id)
        assertFalse(repo.categories().any { it.id == breakfast.id })
        // New entry uses the same persisted selectable nodes.
        assertFalse("New entry must not offer deleted breakfast",
            CategoryTree.selectable(ManualTransactionType.EXPENSE, repo.categories())
                .any { it.name == "早餐" })
    }

    @Test fun backupMustIncludeEmptyCustomCategory() {
        val custom = repo.createCategory(ManualTransactionType.EXPENSE, "验收空分类", null)
        assertTrue(repo.categories().any { it.id == custom.id })
        assertTrue("A full backup must retain categories without bills",
            ManualLedgerMigrationCodec.exportJson(repo.list(), repo.categories()).contains("验收空分类"))
    }

    @Test fun categoryMoveMustPreserveFinancialFields() {
        repo.import(listOf(input("饮食 › 早餐")))
        val before = repo.list().single()
        val breakfast = repo.categories().first { it.name == "早餐" }
        repo.moveCategory(breakfast.id, null)
        val after = repo.list().single()
        assertEquals(before.id, after.id)
        assertEquals(before.amountCents, after.amountCents)
        assertEquals(before.account, after.account)
        assertEquals(before.occurredAtMs, after.occurredAtMs)
        assertEquals(before.note, after.note)
        assertEquals(1, repo.list().size)
    }
}
